{"id":873,"status":"Fixed","summary":"Converting from an interface type to a constructor which @implements itself causes stack overflow.","labels":["Type-Defect","Priority-Medium"],"stars":0,"commentCount":3,"comments":[{"id":0,"commenterId":-2717560201058730511,"content":"// Options: --externs externs/es3.js --property_renaming OFF --variable_renaming OFF --jscomp_warning=checkTypes --js=t.js


// File: t.js
/**
 * @interface
 */
var OtherType = function() {}

/**
 * @implements {MyType}
 * @constructor
 */
var MyType = function() {}

/**
 * @type {MyType}
 */
var x = /** @type {!OtherType} */ (new Object());

Get Infinite recursion in:

PrototypeObjectType.isSubtype @ 350

Options:

- prevent cycles in the inheritance/implements graph
- detect cycles after they are created and exit compilation before any subsequent passes run
- detect and remove cycles after they are created but before any subsequent passes run
- make every subsequent pass robust against cycles in that graph","timestamp":1355368175,"attachments":[]},{"id":1,"commenterId":4865484112040790759,"content":"","timestamp":1355510770,"attachments":[]},{"id":2,"commenterId":-5060162230523776870,"content":"Fixed at r2399","timestamp":1355783425,"attachments":[]}]}

